// The code-block theme, made from the site's palette: five syntax hues at one
// lightness (keywords in the accent's hue), names in ink, comments and
// punctuation faint. The values are read from scales.css (generated by
// docs/redesign/comps/tokens.mts), so the theme can never drift from it.
import { readFileSync } from "node:fs";

// From the project root: Astro bundles its config, so a path relative to
// this module would point into the bundle.
const css = readFileSync("src/styles/scales.css", "utf8");

// The first block is dark (the default), the second light (the toggle).
function block(selector: string) {
  const start = css.indexOf(`${selector} {`);
  const body = css.slice(start, css.indexOf("}", start));
  return Object.fromEntries(
    [...body.matchAll(/--([\w-]+):\s*(#[0-9a-f]{6})/g)].map((m) => [
      m[1],
      m[2],
    ]),
  ) as Record<string, string>;
}

function theme(
  name: string,
  type: "dark" | "light",
  c: Record<string, string>,
) {
  const rule = (scope: string[], foreground: string) => ({
    scope,
    settings: { foreground },
  });
  return {
    name,
    type,
    colors: {
      "editor.background": c.n3,
      "editor.foreground": c.n12,
    },
    tokenColors: [
      rule(["comment", "punctuation.definition.comment"], c.n10),
      rule(["punctuation", "meta.brace", "keyword.operator"], c.n10),
      rule(["variable", "meta.object-literal.key"], c.n12),
      rule(
        [
          "keyword",
          "storage",
          "storage.type",
          "storage.modifier",
          "keyword.control",
          "variable.language",
        ],
        c["syn-kw"],
      ),
      rule(
        ["entity.name.function", "support.function", "meta.function-call"],
        c["syn-fn"],
      ),
      rule(["string", "string.quoted", "string.template"], c["syn-str"]),
      rule(
        [
          "constant",
          "constant.numeric",
          "constant.language",
          "support.constant",
        ],
        c["syn-num"],
      ),
      rule(
        [
          "entity.name.type",
          "support.type",
          "support.class",
          "entity.name.class",
        ],
        c["syn-type"],
      ),
      rule(["support.type.property-name", "entity.name.tag"], c["syn-fn"]),
      rule(["entity.other.attribute-name"], c["syn-num"]),
    ],
  };
}

export const codeThemes = [
  theme("site-dark", "dark", block(":root")),
  theme("site-light", "light", block(':root[data-theme="light"]')),
];
